import 'package:flutter/material.dart';
import 'package:flutter/services.dart';
import 'package:flutter_secure_storage/flutter_secure_storage.dart';
import 'package:image_picker/image_picker.dart';
import 'package:permission_handler/permission_handler.dart';
import 'package:speech_to_text/speech_to_text.dart';
import 'core/providers/gemini_client.dart';
void main()=>runApp(const AiOsApp());
const secureStorage=FlutterSecureStorage();
const native=MethodChannel('ai_os/native');
class AiOsApp extends StatelessWidget{const AiOsApp({super.key});@override Widget build(BuildContext c)=>MaterialApp(title:'AI OS',debugShowCheckedModeBanner:false,theme:ThemeData(useMaterial3:true,colorSchemeSeed:Colors.indigo),home:const MainShell());}
class MainShell extends StatefulWidget{const MainShell({super.key});@override State<MainShell> createState()=>_MainShellState();}
class _MainShellState extends State<MainShell>{int index=0;@override Widget build(BuildContext c){return Scaffold(body:SafeArea(child:IndexedStack(index:index,children:const[ChatPage(),AiRoomPage(),HistoryPage(),SettingsPage()])),bottomNavigationBar:NavigationBar(selectedIndex:index,onDestinationSelected:(v)=>setState(()=>index=v),destinations:const[NavigationDestination(icon:Icon(Icons.chat_bubble_outline),label:'채팅'),NavigationDestination(icon:Icon(Icons.hub_outlined),label:'AI 대화방'),NavigationDestination(icon:Icon(Icons.history),label:'기록'),NavigationDestination(icon:Icon(Icons.settings_outlined),label:'설정')]));}}
class ChatPage extends StatefulWidget{const ChatPage({super.key});@override State<ChatPage> createState()=>_ChatPageState();}
class _ChatPageState extends State<ChatPage>{final input=TextEditingController();final gemini=const GeminiClient();final stt=SpeechToText();final msgs=<Map<String,String>>[];String? attachment;bool busy=false,listening=false;
Future<void> pickDocument()async{try{final r=await native.invokeMapMethod<String,dynamic>('openDocument');if(r!=null&&mounted)setState(()=>attachment=(r['name']??'문서').toString());}catch(e){if(mounted)ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text('문서를 열 수 없습니다: $e')));}}
Future<void> add()async{await showModalBottomSheet<void>(context:context,builder:(x)=>SafeArea(child:Wrap(children:[ListTile(leading:const Icon(Icons.camera_alt_outlined),title:const Text('카메라 촬영'),onTap:()async{Navigator.pop(x);if(await Permission.camera.request().isGranted){final f=await ImagePicker().pickImage(source:ImageSource.camera);if(f!=null&&mounted)setState(()=>attachment=f.name);}}),ListTile(leading:const Icon(Icons.photo_library_outlined),title:const Text('사진 선택'),onTap:()async{Navigator.pop(x);final f=await ImagePicker().pickImage(source:ImageSource.gallery);if(f!=null&&mounted)setState(()=>attachment=f.name);}),ListTile(leading:const Icon(Icons.description_outlined),title:const Text('파일 첨부'),subtitle:const Text('PDF · Office · TXT · MD · CSV · JSON 등'),onTap:(){Navigator.pop(x);pickDocument();}}])));}
Future<void> voice()async{if(listening){await stt.stop();setState(()=>listening=false);return;}if(!await Permission.microphone.request().isGranted)return;final ok=await stt.initialize();if(!ok)return;setState(()=>listening=true);await stt.listen(localeId:'ko_KR',onResult:(r){input.text=r.recognizedWords;input.selection=TextSelection.collapsed(offset:input.text.length);if(r.finalResult&&mounted)setState(()=>listening=false);});}
Future<void> send()async{final q=input.text.trim();if(q.isEmpty&&attachment==null)return;setState((){msgs.add({'u':q.isEmpty?'첨부 문서 분석':q,'a':attachment??''});input.clear();busy=true;});final key=await secureStorage.read(key:'gemini_api_key')??'';String ans;if(key.isNotEmpty){try{ans=await gemini.chat(apiKey:key,prompt:'${q.isEmpty?'첨부 자료를 분석해줘':q}${attachment==null?'':'\n첨부: $attachment'}');}catch(_){ans='연결된 AI가 응답하지 않았습니다. 다른 활성 AI로 전환하거나 설정에서 연결 상태를 확인하세요.';}}else{ans='질문과 첨부 자료를 작업으로 등록했습니다. 현재 실제 응답 가능한 외부/온디바이스 AI가 연결되어 있지 않습니다. 설정에서 무료 AI 연결을 활성화하면 Router가 자동 선택합니다.';}if(mounted)setState((){msgs.add({'u':'','a':ans});attachment=null;busy=false;});}
@override Widget build(BuildContext c)=>Column(children:[const ListTile(title:Text('AI OS',style:TextStyle(fontSize:25,fontWeight:FontWeight.bold))),Expanded(child:msgs.isEmpty?const Center(child:Text('무엇을 도와드릴까요?',style:TextStyle(fontSize:20))):ListView.builder(padding:const EdgeInsets.all(10),itemCount:msgs.length,itemBuilder:(_,i){final m=msgs[i];final user=m['u']!.isNotEmpty;return Align(alignment:user?Alignment.centerRight:Alignment.centerLeft,child:Card(child:Padding(padding:const EdgeInsets.all(12),child:Text(user?m['u']!:m['a']!))));})),if(attachment!=null)ListTile(dense:true,leading:const Icon(Icons.attach_file),title:Text(attachment!),trailing:IconButton(icon:const Icon(Icons.close),onPressed:()=>setState(()=>attachment=null))),if(busy)const LinearProgressIndicator(),Padding(padding:const EdgeInsets.all(8),child:Row(children:[IconButton(onPressed:add,icon:const Icon(Icons.add)),Expanded(child:TextField(controller:input,minLines:1,maxLines:5,decoration:const InputDecoration(hintText:'메시지',border:OutlineInputBorder()))),IconButton(onPressed:voice,icon:Icon(listening?Icons.mic:Icons.mic_none)),IconButton(onPressed:busy?null:send,icon:const Icon(Icons.send))]))]);}
class AiRoomPage extends StatefulWidget{const AiRoomPage({super.key});@override State<AiRoomPage> createState()=>_AiRoomPageState();}
class _AiRoomPageState extends State<AiRoomPage>{final topics=<String>['새 AI 회의'];String topic='새 AI 회의';final input=TextEditingController();final lines=<String>[];void newTopic(){final c=TextEditingController();showDialog<void>(context:context,builder:(d)=>AlertDialog(title:const Text('새 주제'),content:TextField(controller:c,autofocus:true),actions:[TextButton(onPressed:()=>Navigator.pop(d),child:const Text('취소')),FilledButton(onPressed:(){final t=c.text.trim();if(t.isNotEmpty)setState((){topics.add(t);topic=t;lines.clear();});Navigator.pop(d);},child:const Text('생성'))]));}void send(){final q=input.text.trim();if(q.isEmpty)return;setState((){lines.add('나: $q');lines.add('Planner: 요청을 작업으로 분해했습니다.');lines.add('Judge: 실제 AI Provider 응답을 기다립니다.');input.clear();});}@override Widget build(BuildContext c)=>Column(children:[ListTile(title:const Text('AI 대화방',style:TextStyle(fontSize:25,fontWeight:FontWeight.bold)),subtitle:DropdownButton<String>(value:topic,isExpanded:true,items:topics.map((t)=>DropdownMenuItem(value:t,child:Text(t))).toList(),onChanged:(v)=>setState(()=>topic=v!)),trailing:IconButton(icon:const Icon(Icons.add),onPressed:newTopic)),Expanded(child:lines.isEmpty?Center(child:Text('주제: $topic\nAI 회의에 직접 참여할 수 있습니다.',textAlign:TextAlign.center)):ListView.builder(itemCount:lines.length,itemBuilder:(_,i)=>ListTile(title:Text(lines[i])))),Padding(padding:const EdgeInsets.all(8),child:Row(children:[Expanded(child:TextField(controller:input,decoration:const InputDecoration(hintText:'AI 회의에 메시지 입력',border:OutlineInputBorder()))),IconButton(onPressed:send,icon:const Icon(Icons.send))]))]);}
class HistoryPage extends StatelessWidget{const HistoryPage({super.key});@override Widget build(BuildContext c)=>const Center(child:Text('대화 및 작업 기록'));}
class SettingsPage extends StatelessWidget{const SettingsPage({super.key});@override Widget build(BuildContext c)=>ListView(children:[const ListTile(title:Text('설정',style:TextStyle(fontSize:25,fontWeight:FontWeight.bold)),subtitle:Text('AI · API · 권한 · 음성 · 저장공간')),ListTile(leading:const Icon(Icons.mic),title:const Text('마이크 권한'),trailing:TextButton(onPressed:()=>Permission.microphone.request(),child:const Text('요청'))),ListTile(leading:const Icon(Icons.camera_alt),title:const Text('카메라 권한'),trailing:TextButton(onPressed:()=>Permission.camera.request(),child:const Text('요청'))),const SwitchListTile(value:true,onChanged:null,title:Text('무료 AI 우선')),const SwitchListTile(value:false,onChanged:null,title:Text('유료 API 사용 허용')),ListTile(title:const Text('Gemini API Key (선택)'),trailing:IconButton(icon:const Icon(Icons.key),onPressed:(){})),const Divider(),const ListTile(title:Text('AI OS'),subtitle:Text('Version 0.3.0\nCreator: Daehyun Kang'))]);}
